const refs = resolveElementRefs();

/**
 * Re-resolve element refs after shell panel markup lands in the DOM.
 *
 * `refs` and the panel-visibility defaults are captured when this module
 * first evaluates, which may be before the surface classes install their
 * shell panel markup (`Editor.installShellMarkup()` and friends). Those
 * installers call this afterwards to fill in refs that were still null and
 * to re-seed the default panel visibility for panels that just appeared.
 * Refs that already resolved are left untouched, and the visibility
 * defaults are only re-seeded when they actually changed, so late or
 * repeated calls cannot clobber user panel toggles.
 */
function refreshElementRefs() {
  const resolvedRefs = resolveElementRefs();

  for (const key of Object.keys(resolvedRefs)) {
    if (!refs[key]) {
      refs[key] = resolvedRefs[key];
    }
  }

  const panelVisibility = getDefaultPanelVisibilityForCurrentPage();
  const panelVisibilityChanged = Object.keys(panelVisibility).some(
    (key) => panelVisibility[key] !== DEFAULT_PANEL_VISIBILITY[key],
  );

  if (panelVisibilityChanged) {
    Object.assign(DEFAULT_PANEL_VISIBILITY, panelVisibility);
    state.editorVisible = panelVisibility.editorVisible;
    state.previewVisible = panelVisibility.previewVisible;
    state.openLyricVisible = panelVisibility.openLyricVisible;
  }

  syncEditorActivityState();
}

function syncEditorVersionBadge() {
  if (!refs.editorVersionBadge) {
    return;
  }

  const metadataLabel = getEditorMetadataTitle();

  refs.editorVersionBadge.textContent = getEditorVersionBadgeText();
  refs.editorVersionBadge.title = metadataLabel;
  refs.editorVersionBadge.setAttribute('aria-label', metadataLabel);
}

syncEditorVersionBadge();
syncEditorActivityState();

function parseSharedDocumentDateValue(value) {
  const normalizedValue = String(value ?? '').trim();

  if (!normalizedValue) {
    return null;
  }

  const match = normalizedValue.match(
    /^(\d{4})-(\d{2})-(\d{2})(?:[T_\s])(\d{2})[-:](\d{2})[-:](\d{2})$/,
  );

  if (match) {
    const [, yearText, monthText, dayText, hourText, minuteText, secondText] =
      match;
    const year = Number.parseInt(yearText, 10);
    const month = Number.parseInt(monthText, 10);
    const day = Number.parseInt(dayText, 10);
    const hour = Number.parseInt(hourText, 10);
    const minute = Number.parseInt(minuteText, 10);
    const second = Number.parseInt(secondText, 10);
    const parsedDate = new Date(year, month - 1, day, hour, minute, second);

    if (
      parsedDate.getFullYear() === year &&
      parsedDate.getMonth() === month - 1 &&
      parsedDate.getDate() === day &&
      parsedDate.getHours() === hour &&
      parsedDate.getMinutes() === minute &&
      parsedDate.getSeconds() === second
    ) {
      return parsedDate;
    }

    return null;
  }

  const timestamp = Date.parse(normalizedValue);

  if (!Number.isFinite(timestamp)) {
    return null;
  }

  const parsedDate = new Date(timestamp);
  return Number.isNaN(parsedDate.getTime()) ? null : parsedDate;
}

function formatSharedDocumentDateValue(value, options) {
  const parsedDate = parseSharedDocumentDateValue(value);

  if (!parsedDate) {
    return '';
  }

  return new Intl.DateTimeFormat(undefined, options).format(parsedDate);
}

function setSharedDocumentDate(value) {
  const normalizedValue = String(value ?? '').trim();
  const shortLabel = formatSharedDocumentDateValue(normalizedValue, {
    dateStyle: 'medium',
    timeStyle: 'short',
  });

  state.sharedDocumentDate = shortLabel ? normalizedValue : '';

  if (!refs.sharedDocumentDate) {
    return;
  }

  if (!shortLabel) {
    refs.sharedDocumentDate.hidden = true;
    refs.sharedDocumentDate.textContent = '';
    refs.sharedDocumentDate.title = '';
    refs.sharedDocumentDate.removeAttribute('aria-label');
    return;
  }

  const fullLabel = formatSharedDocumentDateValue(normalizedValue, {
    dateStyle: 'full',
    timeStyle: 'medium',
  });

  refs.sharedDocumentDate.hidden = false;
  refs.sharedDocumentDate.textContent = `Shared edit: ${shortLabel}`;
  refs.sharedDocumentDate.title = `Last shared edit: ${fullLabel}`;
  refs.sharedDocumentDate.setAttribute(
    'aria-label',
    `Last shared edit: ${fullLabel}`,
  );
}

function setStatus(message) {
  if (refs.status) {
    refs.status.textContent = message;
  }
}

function supportsLegacyClipboardCopy() {
  if (typeof document.execCommand !== 'function') {
    return false;
  }

  if (typeof document.queryCommandSupported === 'function') {
    try {
      return document.queryCommandSupported('copy');
    } catch (_error) {
      // Fall back to the presence of execCommand below.
    }
  }

  return true;
}

function supportsLegacyClipboardPaste() {
  if (
    typeof document.execCommand !== 'function' ||
    typeof document.queryCommandSupported !== 'function'
  ) {
    return false;
  }

  try {
    return document.queryCommandSupported('paste');
  } catch (_error) {
    return false;
  }
}

function supportsClipboardCopy() {
  return (
    typeof globalThis.navigator?.clipboard?.writeText === 'function' ||
    supportsLegacyClipboardCopy()
  );
}

function supportsClipboardPaste() {
  return (
    typeof globalThis.navigator?.clipboard?.readText === 'function' ||
    supportsLegacyClipboardPaste()
  );
}

function syncEditorActivityState() {
  if (!(refs.editorPanel instanceof HTMLElement)) {
    return;
  }

  refs.editorPanel.dataset.activityState =
    runtime.editorActivityCount > 0 ? 'busy' : 'idle';
}

function startEditorActivity() {
  runtime.editorActivityCount += 1;
  syncEditorActivityState();

  let finished = false;

  return () => {
    if (finished) {
      return;
    }

    finished = true;
    runtime.editorActivityCount = Math.max(0, runtime.editorActivityCount - 1);
    syncEditorActivityState();
  };
}

function updateStatus() {
  const dirtyMark = state.dirty ? ' *' : '';
  const errorText = state.errorCount
    ? ` · ${state.errorCount} lexical ${state.errorCount === 1 ? 'error' : 'errors'}`
    : '';

  setStatus(`${state.fileName}${dirtyMark}${errorText}`);
}

function setErrorCount(nextErrorCount) {
  state.errorCount = nextErrorCount;
  updateStatus();
}

function getCurrentValue() {
  if (
    state.editorMode === 'simple' &&
    refs.simpleEditorTextarea instanceof HTMLTextAreaElement
  ) {
    return refs.simpleEditorTextarea.value;
  }

  return state.editor ? state.editor.getValue() : state.currentDocumentContent;
}

function setCurrentDocumentContent(value) {
  state.currentDocumentContent = String(value ?? '');
}

function setSimpleEditorValue(value) {
  if (!(refs.simpleEditorTextarea instanceof HTMLTextAreaElement)) {
    return;
  }

  refs.simpleEditorTextarea.value = String(value ?? '');
}

function markDirty(nextDirty) {
  state.dirty = nextDirty;
  updateStatus();
}

function setDropActive(active) {
  if (refs.app) {
    refs.app.classList.toggle('drop-active', active);
  }
}

