const OPEN_LYRIC_EDITOR_INFO = Object.freeze({
  name: 'Open Lyric',
  version: '0.1.9-dev',
});

function getCurrentEditorShell() {
  return String(
    globalThis.document?.documentElement?.dataset?.editorShell ?? '',
  ).trim();
}

function getEditorDisplayName() {
  return getCurrentEditorShell() === 'editor-only'
    ? ''
    : OPEN_LYRIC_EDITOR_INFO.name;
}

function getCurrentBrowserLocationUrl() {
  return String(globalThis.location?.href ?? '').trim();
}

function formatEditorVersion(version = OPEN_LYRIC_EDITOR_INFO.version) {
  const normalizedVersion = String(version ?? '').trim();

  if (!normalizedVersion) {
    return '';
  }

  return normalizedVersion.startsWith('v')
    ? normalizedVersion
    : `v${normalizedVersion}`;
}

function getEditorSignature() {
  const editorName = getEditorDisplayName();
  const versionLabel = formatEditorVersion();

  if (editorName && versionLabel) {
    return `${editorName} ${versionLabel}`;
  }

  if (editorName) {
    return editorName;
  }

  return versionLabel ? `Editor ${versionLabel}` : 'Editor';
}

function getEditorVersionBadgeText() {
  const versionLabel = formatEditorVersion();

  return versionLabel ? `Editor ${versionLabel}` : 'Editor';
}

function getEditorMetadataTitle() {
  return [getEditorSignature(), getCurrentBrowserLocationUrl()]
    .filter(Boolean)
    .join(' · ');
}

export {
  OPEN_LYRIC_EDITOR_INFO,
  formatEditorVersion,
  getCurrentBrowserLocationUrl,
  getEditorDisplayName,
  getEditorMetadataTitle,
  getEditorSignature,
  getEditorVersionBadgeText,
};
