import { OLFenceDefinition } from './OLFenceDefinition.ts';

class OLIntro extends OLFenceDefinition {
  constructor() {
    super({
      className: 'OLIntro',
      header: 'Intro',
      kind: 'intro',
      description: 'Intro progression fence.',
      tokenState: 'olIntro',
    });
  }

  validateBody(context) {
    context.validators.validateDirectiveBlock(
      context.bodyLines,
      context.startLineNumber,
      context.markers,
      this.header,
      context.directivePatterns.intro,
      '{p: #3} or {c: Piano }',
    );
  }

  renderPreviewBody(context) {
    return context.helpers.renderChordProgressionLineCollection(
      context.lineEntries,
    );
  }
}

export { OLIntro };
