import {
  LANGUAGE_ID,
  grammar,
  hasChordProgressionText,
  normalizeConfigFieldName,
  startEditorActivity,
  state,
} from './shared.ts';
import { getFenceBlockKind } from '../plugins/OpenLyric/domain/parser/fences.ts';
import {
  detectLanguageCode,
  getSpellcheckSpecification,
  getSpellcheckTokenPatterns,
  hasKhmerBaseLetter,
  normalizeLanguageCode,
  normalizeSpellcheckLookupWord,
  normalizeWord,
} from './spellcheck-common.ts';
import { subscribeToPluginRegistry } from './editor-plugin-registry.ts';
import { createEnglishSpellcheckProvider } from './spellcheck-english-provider.ts';
import { createPluginSpellcheckProvider } from './spellcheck-plugin-provider.ts';
import { logKhmerTime } from './helpers.ts';

const { CONFIG_MULTILINE_FIELD_NAMES } = grammar;

const SPELLCHECK_KHMER_MARKER_MAX_SPREAD_LENGTH = 20;
const SPELLCHECK_MARKER_OWNER = 'open-lyric-spellcheck';
const SPELLCHECK_CODE = 'open-lyric-spellcheck';
const ADD_TO_CUSTOM_DICTIONARY_COMMAND_ID =
  'open-lyric.add-to-custom-dictionary';
const QUICK_FIX_KIND =
  globalThis.monaco?.languages?.CodeActionKind?.QuickFix || 'quickfix';
const SPELLCHECK_CODE_ACTION_LANGUAGE_IDS = [LANGUAGE_ID, 'markdown'];
const SPELLCHECK_DELAY_MS = 250;
const SPELLCHECK_LINE_DELAY_MS = 120;
const SPELLCHECK_SKIPPED_CONFIG_FIELDS = new Set([
  'Key',
  'Tempo',
  'Time',
  'Structure',
  'Attachments',
  'Strumming Patterns',
]);
const spellcheckRuntime = {
  activeMarkers: [],
  codeActionProviderDisposable: null,
  codeActionProviderRegistered: false,
  customDictionaryWordsByLanguage: new Map(),
  excludedWordsByLanguage: new Map(),
  lineTimer: 0,
  lineValidationInFlight: false,
  pendingLineValidationLines: new Set(),
  pendingLineValidationModelUri: '',
  providers: new Map(),
  timer: 0,
  validationRequestId: 0,
};

function getSpellcheckTimingNow() {
  return typeof globalThis.performance?.now === 'function'
    ? globalThis.performance.now()
    : Date.now();
}

function logKhmerSpellcheckTiming(label, startTime, details = '') {
  const durationMs = getSpellcheckTimingNow() - startTime;
  logKhmerTime(
    console.info,
    `${label}: ${durationMs.toFixed(1)}ms${details ? ` ${details}` : ''}`,
  );
  return durationMs;
}

function shouldLogKhmerSpellcheckTiming() {
  return getEnabledSpellcheckLanguageCodes().includes('km');
}

function isKhmerSpellcheckLanguageCode(languageCode) {
  return normalizeLanguageCode(languageCode) === 'km';
}

function getSpellcheckWordCharacterCount(word) {
  return Array.from(String(word || '')).length;
}

function shouldLogKhmerSpellcheckMarkers(model, markers) {
  return Array.isArray(markers)
    ? markers.some((marker) => isKhmerSpellcheckMarker(model, marker))
    : false;
}

function isInvokedSpellcheckCodeActionRequest(context) {
  return (
    Number(context?.trigger) ===
    Number(monaco?.languages?.CodeActionTriggerType?.Invoke || 1)
  );
}

function resetActiveSpellcheckMarkers() {
  spellcheckRuntime.activeMarkers = [];
}

function syncActiveSpellcheckMarkers(model, markers) {
  if (!model) {
    resetActiveSpellcheckMarkers();
    return;
  }

  spellcheckRuntime.activeMarkers = Array.isArray(markers)
    ? markers.slice()
    : [];
}

function sortSpellcheckMarkers(markers) {
  return (Array.isArray(markers) ? markers.slice() : []).sort((left, right) => {
    if (left.startLineNumber !== right.startLineNumber) {
      return left.startLineNumber - right.startLineNumber;
    }

    return left.startColumn - right.startColumn;
  });
}

function getModelSpellcheckMarkers(model) {
  if (!model || typeof monaco?.editor?.getModelMarkers !== 'function') {
    return spellcheckRuntime.activeMarkers.slice();
  }

  return sortSpellcheckMarkers(
    monaco.editor.getModelMarkers({
      owner: SPELLCHECK_MARKER_OWNER,
      resource: model.uri,
    }),
  );
}

function supportsSpellcheckQuickFixLanguage(languageCode) {
  const normalizedLanguageCode = normalizeLanguageCode(languageCode);
  if (!normalizedLanguageCode) {
    return false;
  }

  return (
    typeof getSpellcheckProvider(normalizedLanguageCode)?.getSuggestions ===
    'function'
  );
}

function disposeSpellcheckProvider(languageCode) {
  spellcheckRuntime.providers.get(languageCode)?.dispose?.();
  spellcheckRuntime.providers.delete(languageCode);
}

subscribeToPluginRegistry(({ spellcheckLanguageCodes = [] }) => {
  spellcheckLanguageCodes.forEach((languageCode) => {
    disposeSpellcheckProvider(languageCode);
  });
});

function createSpellcheckProvider(languageCode, specification) {
  if (languageCode === 'en') {
    return createEnglishSpellcheckProvider();
  }

  if (!specification) {
    return null;
  }

  if (typeof specification.providerFactory === 'function') {
    return specification.providerFactory(specification);
  }

  return createPluginSpellcheckProvider(specification);
}

function getSpellcheckProvider(languageCode) {
  const normalizedLanguageCode = normalizeLanguageCode(languageCode);
  if (!normalizedLanguageCode) {
    return null;
  }

  const specification = getSpellcheckSpecification(normalizedLanguageCode);
  if (!specification) {
    disposeSpellcheckProvider(normalizedLanguageCode);
    return null;
  }

  if (!spellcheckRuntime.providers.has(normalizedLanguageCode)) {
    const provider = createSpellcheckProvider(
      normalizedLanguageCode,
      specification,
    );
    if (!provider) {
      return null;
    }

    spellcheckRuntime.providers.set(normalizedLanguageCode, provider);
  }

  return spellcheckRuntime.providers.get(normalizedLanguageCode) || null;
}

function normalizeSpellcheckCustomDictionaryWord(word, languageCode) {
  const normalizedLanguageCode = normalizeLanguageCode(languageCode);

  if (!normalizedLanguageCode) {
    return '';
  }

  return normalizeSpellcheckLookupWord(word, normalizedLanguageCode);
}

function normalizeSpellcheckCustomDictionaryWords(languageCode, words) {
  const normalizedLanguageCode = normalizeLanguageCode(languageCode);

  if (!normalizedLanguageCode) {
    return [];
  }

  const normalizedWords = new Set();
  const sourceWords = Array.isArray(words) ? words : [words];

  sourceWords.forEach((word) => {
    const normalizedWord = normalizeSpellcheckCustomDictionaryWord(
      word,
      normalizedLanguageCode,
    );

    if (normalizedWord) {
      normalizedWords.add(normalizedWord);
    }
  });

  return Array.from(normalizedWords).sort((left, right) =>
    left.localeCompare(right),
  );
}

function setSpellcheckCustomDictionaryWords(languageCode, words) {
  const normalizedLanguageCode = normalizeLanguageCode(languageCode);

  if (!normalizedLanguageCode) {
    return [];
  }

  const normalizedWords = normalizeSpellcheckCustomDictionaryWords(
    normalizedLanguageCode,
    words,
  );

  if (!normalizedWords.length) {
    spellcheckRuntime.customDictionaryWordsByLanguage.delete(
      normalizedLanguageCode,
    );
    return normalizedWords;
  }

  spellcheckRuntime.customDictionaryWordsByLanguage.set(
    normalizedLanguageCode,
    new Set(normalizedWords),
  );

  return normalizedWords;
}

function setSpellcheckExcludedWords(languageCode, words) {
  const normalizedLanguageCode = normalizeLanguageCode(languageCode);

  if (!normalizedLanguageCode) {
    return [];
  }

  const normalizedWords = normalizeSpellcheckCustomDictionaryWords(
    normalizedLanguageCode,
    words,
  );

  if (!normalizedWords.length) {
    spellcheckRuntime.excludedWordsByLanguage.delete(normalizedLanguageCode);
    return normalizedWords;
  }

  spellcheckRuntime.excludedWordsByLanguage.set(
    normalizedLanguageCode,
    new Set(normalizedWords),
  );

  return normalizedWords;
}

async function pruneSpellcheckCustomDictionaryWords(languageCode, words) {
  const normalizedLanguageCode = normalizeLanguageCode(languageCode);
  const normalizedWords = normalizeSpellcheckCustomDictionaryWords(
    normalizedLanguageCode,
    words,
  );

  if (!normalizedLanguageCode || !normalizedWords.length) {
    return normalizedWords;
  }

  const provider = getSpellcheckProvider(normalizedLanguageCode);

  if (!provider?.checkWords) {
    return normalizedWords;
  }

  const ready = await ensureSpellcheckLanguageReady(normalizedLanguageCode);

  if (!ready || !provider.isReady()) {
    return normalizedWords;
  }

  try {
    const results = await provider.checkWords(normalizedWords);

    if (!(results instanceof Map)) {
      return normalizedWords;
    }

    return normalizedWords.filter((word) => results.get(word) === false);
  } catch (error) {
    console.error(
      `Failed to prune ${normalizedLanguageCode} custom dictionary words.`,
      error,
    );
    return normalizedWords;
  }
}

async function checkSpellcheckWordValidity(languageCode, word) {
  const normalizedLanguageCode = normalizeLanguageCode(languageCode);
  const normalizedWord = normalizeSpellcheckCustomDictionaryWord(
    word,
    normalizedLanguageCode,
  );

  if (!normalizedLanguageCode || !normalizedWord) {
    return null;
  }

  const provider = getSpellcheckProvider(normalizedLanguageCode);

  if (!provider?.checkWords) {
    return null;
  }

  const ready = await ensureSpellcheckLanguageReady(normalizedLanguageCode);

  if (!ready || !provider.isReady()) {
    return null;
  }

  if (!provider.shouldCheckWord(normalizedWord)) {
    return null;
  }

  try {
    const results = await provider.checkWords([normalizedWord]);

    if (!(results instanceof Map)) {
      return null;
    }

    return results.get(normalizedWord) !== false;
  } catch (error) {
    console.error(
      `Failed to check ${normalizedLanguageCode} spellcheck word validity.`,
      error,
    );
    return null;
  }
}

function hasSpellcheckCustomDictionaryWord(languageCode, word) {
  const normalizedLanguageCode = normalizeLanguageCode(languageCode);

  if (!normalizedLanguageCode) {
    return false;
  }

  const normalizedWord = normalizeSpellcheckCustomDictionaryWord(
    word,
    normalizedLanguageCode,
  );

  if (!normalizedWord) {
    return false;
  }

  return Boolean(
    spellcheckRuntime.customDictionaryWordsByLanguage
      .get(normalizedLanguageCode)
      ?.has(normalizedWord),
  );
}

function hasSpellcheckExcludedWord(languageCode, word) {
  const normalizedLanguageCode = normalizeLanguageCode(languageCode);

  if (!normalizedLanguageCode) {
    return false;
  }

  const normalizedWord = normalizeSpellcheckCustomDictionaryWord(
    word,
    normalizedLanguageCode,
  );

  if (!normalizedWord) {
    return false;
  }

  return Boolean(
    spellcheckRuntime.excludedWordsByLanguage
      .get(normalizedLanguageCode)
      ?.has(normalizedWord),
  );
}

function getSpellcheckCustomDictionaryPrefixSuggestions(
  languageCode,
  word,
  limit = 8,
) {
  const normalizedLanguageCode = normalizeLanguageCode(languageCode);
  const normalizedPrefix = normalizeSpellcheckCustomDictionaryWord(
    word,
    normalizedLanguageCode,
  );
  const customDictionaryWords = normalizedLanguageCode
    ? spellcheckRuntime.customDictionaryWordsByLanguage.get(
        normalizedLanguageCode,
      )
    : null;
  const maxSuggestions = Math.max(1, Number(limit) || 8);

  if (!normalizedLanguageCode || !normalizedPrefix || !customDictionaryWords) {
    return [];
  }

  const normalizedPrefixLower = normalizedPrefix.toLocaleLowerCase();

  return Array.from(customDictionaryWords)
    .filter((customWord) => {
      return customWord.toLocaleLowerCase().startsWith(normalizedPrefixLower);
    })
    .sort((left, right) => {
      if (left.length !== right.length) {
        return left.length - right.length;
      }

      return left.localeCompare(right, undefined, {
        sensitivity: 'base',
      });
    })
    .slice(0, maxSuggestions);
}

function getGlobalPattern(pattern) {
  const flags = pattern.flags.includes('g')
    ? pattern.flags
    : `${pattern.flags}g`;

  return new RegExp(pattern.source, flags);
}

async function applyTranscriptWordSegmentation(text, specification, provider) {
  if (
    !(specification?.wordPattern instanceof RegExp) ||
    typeof provider?.getSegmentationSuggestion !== 'function'
  ) {
    return text;
  }

  const matches = Array.from(
    text.matchAll(getGlobalPattern(specification.wordPattern)),
  );

  if (!matches.length) {
    return text;
  }

  const replacements = new Map();

  await Promise.all(
    matches.map(async (match) => {
      const word = match?.[0] ?? '';

      if (!word || replacements.has(word)) {
        return;
      }

      const replacement = await provider.getSegmentationSuggestion(word);

      if (
        typeof replacement === 'string' &&
        replacement &&
        replacement !== word
      ) {
        replacements.set(word, replacement);
      }
    }),
  );

  if (!replacements.size) {
    return text;
  }

  let nextText = '';
  let lastIndex = 0;

  matches.forEach((match) => {
    const word = match?.[0] ?? '';
    const startIndex = Number(match?.index);

    if (!word || !Number.isInteger(startIndex) || startIndex < lastIndex) {
      return;
    }

    nextText += text.slice(lastIndex, startIndex);
    nextText += replacements.get(word) || word;
    lastIndex = startIndex + word.length;
  });

  nextText += text.slice(lastIndex);
  return nextText;
}

async function postProcessTranscriptText(languageCode, text) {
  const normalizedText = String(text || '');
  const normalizedLanguageCode = normalizeLanguageCode(languageCode);

  if (!normalizedText || !normalizedLanguageCode) {
    return normalizedText;
  }

  const specification = getSpellcheckSpecification(normalizedLanguageCode);
  const provider = getSpellcheckProvider(normalizedLanguageCode);

  if (!specification || !provider) {
    return normalizedText;
  }

  const finishEditorActivity =
    typeof provider.postProcessTranscriptText === 'function' ||
    typeof provider.getSegmentationSuggestion === 'function'
      ? startEditorActivity()
      : null;

  try {
    if (typeof provider.postProcessTranscriptText === 'function') {
      const processedText = await provider.postProcessTranscriptText(
        normalizedText,
        {
          languageCode: normalizedLanguageCode,
          specification,
        },
      );

      return typeof processedText === 'string' ? processedText : normalizedText;
    }

    return applyTranscriptWordSegmentation(
      normalizedText,
      specification,
      provider,
    );
  } catch (error) {
    console.error(
      `Failed to post-process transcript text for ${normalizedLanguageCode}.`,
      error,
    );
    return normalizedText;
  } finally {
    finishEditorActivity?.();
  }
}

function isSpellcheckLanguageEnabled(languageCode) {
  const normalizedLanguageCode = normalizeLanguageCode(languageCode);
  return normalizedLanguageCode
    ? Boolean(state.spellcheckLanguageStates[normalizedLanguageCode])
    : false;
}

function getEnabledSpellcheckLanguageCodes() {
  return Array.from(
    new Set(
      getSpellcheckTokenPatterns()
        .map(({ languageCode }) => languageCode)
        .map(normalizeLanguageCode)
        .filter((languageCode) => isSpellcheckLanguageEnabled(languageCode)),
    ),
  );
}

function getReadySpellcheckLanguageCodes() {
  return getEnabledSpellcheckLanguageCodes().filter((languageCode) =>
    getSpellcheckProvider(languageCode)?.isReady(),
  );
}

function hasEnabledSpellcheckLanguages() {
  return getEnabledSpellcheckLanguageCodes().length > 0;
}

function hasReadySpellcheckProviders() {
  return getReadySpellcheckLanguageCodes().length > 0;
}

async function ensureSpellcheckLanguageReady(languageCode) {
  const normalizedLanguageCode = normalizeLanguageCode(languageCode);
  const provider = getSpellcheckProvider(normalizedLanguageCode);

  if (!provider) {
    return false;
  }

  try {
    return Boolean(await provider.initialize());
  } catch (error) {
    console.error(
      `Failed to initialize ${normalizedLanguageCode} spellcheck.`,
      error,
    );
    return false;
  }
}

function addPatternRanges(line, pattern, ranges) {
  for (const match of line.matchAll(pattern)) {
    ranges.push({
      start: match.index,
      end: match.index + match[0].length,
    });
  }
}

function overlapsIgnoredRange(start, end, ranges) {
  return ranges.some((range) => start < range.end && end > range.start);
}

function createValidationBatch() {
  return {
    occurrencesByLanguage: new Map(),
    requestsByLanguage: new Map(),
  };
}

function queueSpellcheckOccurrence(
  validationBatch,
  languageCode,
  word,
  lineNumber,
  startColumn,
  endColumn,
) {
  const provider = getSpellcheckProvider(languageCode);
  if (!provider?.isReady() || !provider.shouldCheckWord(word)) {
    return;
  }

  const isExcludedWord = hasSpellcheckExcludedWord(languageCode, word);

  if (
    !isExcludedWord &&
    hasSpellcheckCustomDictionaryWord(languageCode, word)
  ) {
    return;
  }

  if (!isExcludedWord) {
    if (!validationBatch.requestsByLanguage.has(languageCode)) {
      validationBatch.requestsByLanguage.set(languageCode, new Set());
    }
    validationBatch.requestsByLanguage.get(languageCode).add(word);
  }

  if (!validationBatch.occurrencesByLanguage.has(languageCode)) {
    validationBatch.occurrencesByLanguage.set(languageCode, []);
  }
  validationBatch.occurrencesByLanguage.get(languageCode).push({
    endColumn,
    lineNumber,
    startColumn,
    forceMarker: isExcludedWord,
    word,
  });
}

function createSpellcheckMarker(
  lineNumber,
  startColumn,
  endColumn,
  word,
  languageCode,
) {
  const hasQuickFix = supportsSpellcheckQuickFixLanguage(languageCode);
  const markerWord = formatSpellcheckMarkerMessageWord(word, languageCode);

  return {
    severity: monaco.MarkerSeverity.Warning,
    source: 'spellcheck',
    code: hasQuickFix ? SPELLCHECK_CODE : undefined,
    origin: normalizeLanguageCode(languageCode) || undefined,
    message: hasQuickFix
      ? `Possible misspelling: ${markerWord}. Use Quick Fix for suggestions.`
      : `Possible misspelling: ${markerWord}.`,
    startLineNumber: lineNumber,
    startColumn,
    endLineNumber: lineNumber,
    endColumn,
  };
}

function collectTextSegmentSpellcheck(
  text,
  lineNumber,
  columnOffset,
  validationBatch,
  ignoredRanges = [],
) {
  if (!text) {
    return;
  }

  getSpellcheckTokenPatterns().forEach(({ languageCode, pattern }) => {
    if (!isSpellcheckLanguageEnabled(languageCode)) {
      return;
    }

    const provider = getSpellcheckProvider(languageCode);
    if (!provider?.isReady()) {
      return;
    }

    pattern.lastIndex = 0;

    for (const match of text.matchAll(pattern)) {
      const startOffset = match.index;
      const endOffset = startOffset + match[0].length;

      if (overlapsIgnoredRange(startOffset, endOffset, ignoredRanges)) {
        continue;
      }

      queueSpellcheckOccurrence(
        validationBatch,
        languageCode,
        match[0],
        lineNumber,
        columnOffset + startOffset,
        columnOffset + endOffset,
      );
    }
  });
}

function scanMarkdownLine(
  line,
  lineNumber,
  validationBatch,
  shouldCollect = true,
) {
  if (!shouldCollect || !line.trim()) {
    return;
  }

  const ignoredRanges = [];
  addPatternRanges(line, /`[^`]*`/g, ignoredRanges);
  addPatternRanges(line, /!\[[^\]]*\]\([^\)]+\)/g, ignoredRanges);
  addPatternRanges(line, /\[[^\]]+\]\([^\)]+\)/g, ignoredRanges);
  addPatternRanges(line, /https?:\/\/\S+/g, ignoredRanges);
  addPatternRanges(line, /<[^>]+>/g, ignoredRanges);

  collectTextSegmentSpellcheck(
    line,
    lineNumber,
    1,
    validationBatch,
    ignoredRanges,
  );
}

function scanLyricLine(
  line,
  lineNumber,
  validationBatch,
  shouldCollect = true,
) {
  if (!shouldCollect || !line.trim() || line.trimStart().startsWith('//')) {
    return;
  }

  const ignoredRanges = [];
  addPatternRanges(line, /\[[^\]]*\]/g, ignoredRanges);
  addPatternRanges(line, /\{[^\}]*\}/g, ignoredRanges);

  collectTextSegmentSpellcheck(
    line,
    lineNumber,
    1,
    validationBatch,
    ignoredRanges,
  );
}

function scanOutroLine(
  line,
  lineNumber,
  validationBatch,
  shouldCollect = true,
) {
  if (!shouldCollect || !line.trim() || line.trimStart().startsWith('//')) {
    return;
  }

  if (hasChordProgressionText(line) || /^\s*\{[cp]:/.test(line)) {
    return;
  }

  scanLyricLine(line, lineNumber, validationBatch, true);
}

function scanConfigLine(
  line,
  lineNumber,
  validationBatch,
  activeMultilineField = '',
  shouldCollect = true,
) {
  if (!line.trim() || line.trimStart().startsWith('//')) {
    return activeMultilineField;
  }

  const configEntryMatch = line.match(/^\s*-\s*([^:]+?)\s*:\s*(.*)$/);
  if (!configEntryMatch) {
    if (
      shouldCollect &&
      !SPELLCHECK_SKIPPED_CONFIG_FIELDS.has(activeMultilineField)
    ) {
      collectTextSegmentSpellcheck(line, lineNumber, 1, validationBatch);
    }

    return activeMultilineField;
  }

  const fieldName = normalizeConfigFieldName(configEntryMatch[1]);
  const nextActiveMultilineField = CONFIG_MULTILINE_FIELD_NAMES.includes(
    fieldName,
  )
    ? fieldName
    : '';

  if (SPELLCHECK_SKIPPED_CONFIG_FIELDS.has(fieldName)) {
    return nextActiveMultilineField;
  }

  if (shouldCollect) {
    const colonOffset = line.indexOf(':');
    const valueText = line.slice(colonOffset + 1);
    collectTextSegmentSpellcheck(
      valueText,
      lineNumber,
      colonOffset + 2,
      validationBatch,
    );
  }

  return nextActiveMultilineField;
}

function collectModelSpellcheckBatch(model, targetLineNumbers = null) {
  const validationBatch = createValidationBatch();
  const lines = model.getLinesContent();
  let openLyricFenceKind = null;
  let activeConfigMultilineField = '';
  let insideGenericCodeFence = false;

  for (let lineIndex = 0; lineIndex < lines.length; lineIndex += 1) {
    const line = lines[lineIndex];
    const lineNumber = lineIndex + 1;
    const shouldCollect =
      !(targetLineNumbers instanceof Set) || targetLineNumbers.has(lineNumber);

    if (insideGenericCodeFence) {
      if (/^\s*```\s*$/.test(line)) {
        insideGenericCodeFence = false;
      }
      continue;
    }

    if (openLyricFenceKind) {
      if (/^\s*```\s*$/.test(line)) {
        openLyricFenceKind = null;
        activeConfigMultilineField = '';
        continue;
      }

      if (openLyricFenceKind === 'config') {
        activeConfigMultilineField = scanConfigLine(
          line,
          lineNumber,
          validationBatch,
          activeConfigMultilineField,
          shouldCollect,
        );
      } else if (
        openLyricFenceKind === 'lyric' ||
        openLyricFenceKind === 'freeText'
      ) {
        scanLyricLine(line, lineNumber, validationBatch, shouldCollect);
      } else if (openLyricFenceKind === 'outro') {
        scanOutroLine(line, lineNumber, validationBatch, shouldCollect);
      }

      continue;
    }

    const openLyricFenceMatch = line.match(/^\s*```ol:(.*?)\s*$/);
    if (openLyricFenceMatch) {
      openLyricFenceKind = getFenceBlockKind(openLyricFenceMatch[1].trim());
      activeConfigMultilineField = '';
      continue;
    }

    if (/^\s*```/.test(line)) {
      insideGenericCodeFence = true;
      continue;
    }

    scanMarkdownLine(line, lineNumber, validationBatch, shouldCollect);
  }

  return validationBatch;
}

async function resolveValidationMarkers(validationBatch) {
  const resultsByLanguage = new Map();
  const shouldLogTiming = validationBatch.requestsByLanguage.has('km');
  const resolveStartTime = shouldLogTiming ? getSpellcheckTimingNow() : 0;
  const requestedKhmerWordCount =
    validationBatch.requestsByLanguage.get('km')?.size || 0;

  await Promise.all(
    Array.from(validationBatch.requestsByLanguage.entries()).map(
      async ([languageCode, words]) => {
        const provider = getSpellcheckProvider(languageCode);
        if (!provider?.isReady()) {
          return;
        }

        const normalizedLanguageCode =
          normalizeLanguageCode(languageCode) || languageCode;
        const shouldLogLanguageTiming = normalizedLanguageCode === 'km';
        const languageStartTime = shouldLogLanguageTiming
          ? getSpellcheckTimingNow()
          : 0;

        try {
          const languageResults = await provider.checkWords(Array.from(words));
          resultsByLanguage.set(languageCode, languageResults);

          if (shouldLogLanguageTiming) {
            logKhmerSpellcheckTiming(
              'resolve markers batch',
              languageStartTime,
              `language=${normalizedLanguageCode} words=${words.size}`,
            );
          }
        } catch (error) {
          console.error(
            `Failed to validate ${languageCode} spellcheck.`,
            error,
          );
        }
      },
    ),
  );

  const markers = [];

  validationBatch.occurrencesByLanguage.forEach((occurrences, languageCode) => {
    const languageResults = resultsByLanguage.get(languageCode);

    occurrences.forEach((occurrence) => {
      if (
        !occurrence.forceMarker &&
        (!languageResults || languageResults.get(occurrence.word) !== false)
      ) {
        return;
      }

      markers.push(
        createSpellcheckMarker(
          occurrence.lineNumber,
          occurrence.startColumn,
          occurrence.endColumn,
          occurrence.word,
          languageCode,
        ),
      );
    });
  });

  const sortedMarkers = sortSpellcheckMarkers(markers);

  if (shouldLogTiming) {
    logKhmerSpellcheckTiming(
      'resolve markers total',
      resolveStartTime,
      `words=${requestedKhmerWordCount} markers=${sortedMarkers.length}`,
    );
  }

  return sortedMarkers;
}

function invalidateSpellcheckValidation() {
  spellcheckRuntime.validationRequestId += 1;
  return spellcheckRuntime.validationRequestId;
}

function shouldApplySpellcheckMarkers(model, requestId, modelVersionId) {
  const activeModel = state.editor?.getModel();
  if (!activeModel || activeModel !== model) {
    return false;
  }

  if (requestId !== spellcheckRuntime.validationRequestId) {
    return false;
  }

  if (model.getVersionId() !== modelVersionId) {
    scheduleSpellcheck();
    return false;
  }

  return true;
}

function commitSpellcheckMarkers(model, markers) {
  const normalizedMarkers = sortSpellcheckMarkers(markers);

  monaco.editor.setModelMarkers(
    model,
    SPELLCHECK_MARKER_OWNER,
    normalizedMarkers,
  );
  syncActiveSpellcheckMarkers(model, normalizedMarkers);
}

function applySpellcheckMarkers(model, requestId, modelVersionId, markers) {
  if (!shouldApplySpellcheckMarkers(model, requestId, modelVersionId)) {
    return;
  }

  commitSpellcheckMarkers(model, markers);
}

function applySpellcheckMarkersForLines(
  model,
  requestId,
  modelVersionId,
  targetLineNumbers,
  markers,
) {
  if (!shouldApplySpellcheckMarkers(model, requestId, modelVersionId)) {
    return;
  }

  const existingMarkers = getModelSpellcheckMarkers(model).filter(
    (marker) =>
      !targetLineNumbers.has(marker.startLineNumber) &&
      !targetLineNumbers.has(marker.endLineNumber),
  );

  commitSpellcheckMarkers(model, existingMarkers.concat(markers));
}

function normalizeChangedLineNumbers(lineNumbers, model) {
  const normalizedLineNumbers = new Set();
  const lineCount = Math.max(1, Number(model?.getLineCount?.() || 0));

  if (!(lineNumbers instanceof Set)) {
    return normalizedLineNumbers;
  }

  lineNumbers.forEach((lineNumber) => {
    const normalizedLineNumber = Number(lineNumber);
    if (!Number.isInteger(normalizedLineNumber)) {
      return;
    }

    if (normalizedLineNumber < 1 || normalizedLineNumber > lineCount) {
      return;
    }

    normalizedLineNumbers.add(normalizedLineNumber);
  });

  return normalizedLineNumbers;
}

async function validateSpellingModel(model) {
  const requestId = invalidateSpellcheckValidation();
  const shouldLogTiming = shouldLogKhmerSpellcheckTiming();
  const validationStartTime = shouldLogTiming ? getSpellcheckTimingNow() : 0;
  let markerCount = 0;

  if (!hasEnabledSpellcheckLanguages() || !hasReadySpellcheckProviders()) {
    clearSpellcheckMarkers(model);
    return;
  }

  const finishEditorActivity = startEditorActivity();

  try {
    const modelVersionId = model.getVersionId();
    const validationBatch = collectModelSpellcheckBatch(model);

    if (!validationBatch.occurrencesByLanguage.size) {
      applySpellcheckMarkers(model, requestId, modelVersionId, []);
      return;
    }

    const markers = await resolveValidationMarkers(validationBatch);
    markerCount = markers.length;
    applySpellcheckMarkers(model, requestId, modelVersionId, markers);
  } finally {
    finishEditorActivity();

    if (shouldLogTiming) {
      logKhmerSpellcheckTiming(
        'full validation',
        validationStartTime,
        `markers=${markerCount}`,
      );
    }
  }
}

async function validateSpellingModelLines(model, lineNumbers) {
  const targetLineNumbers = normalizeChangedLineNumbers(lineNumbers, model);
  if (!targetLineNumbers.size) {
    return;
  }

  const requestId = invalidateSpellcheckValidation();
  const shouldLogTiming = shouldLogKhmerSpellcheckTiming();
  const validationStartTime = shouldLogTiming ? getSpellcheckTimingNow() : 0;
  const lineNumberList = shouldLogTiming
    ? Array.from(targetLineNumbers).sort((left, right) => left - right)
    : [];
  let markerCount = 0;

  if (!hasEnabledSpellcheckLanguages() || !hasReadySpellcheckProviders()) {
    clearSpellcheckMarkers(model);
    return;
  }

  const finishEditorActivity = startEditorActivity();

  try {
    const modelVersionId = model.getVersionId();
    const validationBatch = collectModelSpellcheckBatch(
      model,
      targetLineNumbers,
    );
    const markers = validationBatch.occurrencesByLanguage.size
      ? await resolveValidationMarkers(validationBatch)
      : [];
    markerCount = markers.length;

    applySpellcheckMarkersForLines(
      model,
      requestId,
      modelVersionId,
      targetLineNumbers,
      markers,
    );
  } finally {
    finishEditorActivity();

    if (shouldLogTiming) {
      logKhmerSpellcheckTiming(
        'line validation',
        validationStartTime,
        `lines=${lineNumberList.join(',')} markers=${markerCount}`,
      );
    }
  }
}

function clearSpellcheckTimer() {
  window.clearTimeout(spellcheckRuntime.timer);
  spellcheckRuntime.timer = 0;
}

function clearPendingLineValidation() {
  window.clearTimeout(spellcheckRuntime.lineTimer);
  spellcheckRuntime.lineTimer = 0;
  spellcheckRuntime.pendingLineValidationLines.clear();
  spellcheckRuntime.pendingLineValidationModelUri = '';
}

async function flushPendingLineValidation() {
  spellcheckRuntime.lineTimer = 0;

  if (spellcheckRuntime.lineValidationInFlight) {
    return;
  }

  const model = state.editor?.getModel();
  if (!model) {
    clearPendingLineValidation();
    return;
  }

  const modelUri = model.uri?.toString?.() || '';
  if (
    spellcheckRuntime.pendingLineValidationModelUri &&
    spellcheckRuntime.pendingLineValidationModelUri !== modelUri
  ) {
    clearPendingLineValidation();
    return;
  }

  const lineNumbers = normalizeChangedLineNumbers(
    spellcheckRuntime.pendingLineValidationLines,
    model,
  );
  spellcheckRuntime.pendingLineValidationLines.clear();
  spellcheckRuntime.pendingLineValidationModelUri = modelUri;

  if (!lineNumbers.size) {
    return;
  }

  spellcheckRuntime.lineValidationInFlight = true;

  try {
    await validateSpellingModelLines(model, lineNumbers);
  } finally {
    spellcheckRuntime.lineValidationInFlight = false;

    if (spellcheckRuntime.pendingLineValidationLines.size) {
      spellcheckRuntime.lineTimer = window.setTimeout(() => {
        void flushPendingLineValidation();
      }, SPELLCHECK_LINE_DELAY_MS);
    }
  }
}

function queueLineSpellcheckValidation(model, lineNumbers) {
  const normalizedLineNumbers = normalizeChangedLineNumbers(lineNumbers, model);
  if (!normalizedLineNumbers.size) {
    return false;
  }

  const modelUri = model?.uri?.toString?.() || '';
  if (
    spellcheckRuntime.pendingLineValidationModelUri &&
    spellcheckRuntime.pendingLineValidationModelUri !== modelUri
  ) {
    clearPendingLineValidation();
  }

  spellcheckRuntime.pendingLineValidationModelUri = modelUri;
  normalizedLineNumbers.forEach((lineNumber) => {
    spellcheckRuntime.pendingLineValidationLines.add(lineNumber);
  });

  window.clearTimeout(spellcheckRuntime.lineTimer);

  if (!spellcheckRuntime.lineValidationInFlight) {
    void flushPendingLineValidation();
    return true;
  }

  spellcheckRuntime.lineTimer = window.setTimeout(() => {
    void flushPendingLineValidation();
  }, SPELLCHECK_LINE_DELAY_MS);

  return true;
}

function clearSpellcheckMarkers(model = state.editor?.getModel()) {
  clearSpellcheckTimer();
  clearPendingLineValidation();
  invalidateSpellcheckValidation();

  if (!model) {
    resetActiveSpellcheckMarkers();
    return;
  }

  monaco.editor.setModelMarkers(model, SPELLCHECK_MARKER_OWNER, []);
  syncActiveSpellcheckMarkers(model, []);
}

function getContentChangeLineNumbers(contentChangeEvent) {
  const lineNumbers = new Set();

  if (!Array.isArray(contentChangeEvent?.changes)) {
    return lineNumbers;
  }

  contentChangeEvent.changes.forEach((change) => {
    const startLineNumber = Math.max(
      1,
      Number(change?.range?.startLineNumber) || 1,
    );
    const endLineNumber = Math.max(
      startLineNumber,
      Number(change?.range?.endLineNumber) || startLineNumber,
    );
    const insertedLineCount =
      String(change?.text || '')
        .replace(/\r\n?/g, '\n')
        .split('\n').length - 1;

    for (
      let lineNumber = startLineNumber;
      lineNumber <= endLineNumber + insertedLineCount;
      lineNumber += 1
    ) {
      lineNumbers.add(lineNumber);
    }
  });

  return lineNumbers;
}

function hasStructuralSpellcheckContentChange(contentChangeEvent) {
  if (contentChangeEvent?.isFlush) {
    return true;
  }

  if (!Array.isArray(contentChangeEvent?.changes)) {
    return false;
  }

  return contentChangeEvent.changes.some((change) => {
    const startLineNumber = Number(change?.range?.startLineNumber) || 1;
    const endLineNumber =
      Number(change?.range?.endLineNumber) || startLineNumber;
    const normalizedText = String(change?.text || '').replace(/\r\n?/g, '\n');

    return startLineNumber !== endLineNumber || normalizedText.includes('\n');
  });
}

function handleSpellcheckContentChange(
  model = state.editor?.getModel(),
  contentChangeEvent = null,
) {
  if (!model) {
    return false;
  }

  const contentChanges = Array.isArray(contentChangeEvent?.changes)
    ? contentChangeEvent.changes
    : [];
  if (!contentChanges.length) {
    return false;
  }

  if (hasStructuralSpellcheckContentChange(contentChangeEvent)) {
    clearSpellcheckTimer();
    clearPendingLineValidation();
    void validateSpellingModel(model);
    return true;
  }

  const editedLineNumbers = getContentChangeLineNumbers(contentChangeEvent);
  if (!editedLineNumbers.size) {
    return false;
  }

  clearSpellcheckTimer();
  return queueLineSpellcheckValidation(model, editedLineNumbers);
}

function scheduleSpellcheck() {
  const model = state.editor?.getModel();

  clearSpellcheckTimer();
  clearPendingLineValidation();

  if (!model) {
    return;
  }

  if (!hasEnabledSpellcheckLanguages()) {
    clearSpellcheckMarkers(model);
    return;
  }

  if (!hasReadySpellcheckProviders()) {
    clearSpellcheckMarkers(model);
    return;
  }

  spellcheckRuntime.timer = window.setTimeout(() => {
    const activeModel = state.editor?.getModel();
    if (
      !activeModel ||
      !hasEnabledSpellcheckLanguages() ||
      !hasReadySpellcheckProviders()
    ) {
      clearSpellcheckMarkers(activeModel);
      return;
    }

    void validateSpellingModel(activeModel);
  }, SPELLCHECK_DELAY_MS);
}

async function refreshSpellcheckNow(model = state.editor?.getModel()) {
  clearSpellcheckTimer();
  clearPendingLineValidation();

  if (!model) {
    return;
  }

  const finishEditorActivity = startEditorActivity();

  try {
    await ensureSpellcheckReady(getEnabledSpellcheckLanguageCodes());
    await validateSpellingModel(model);
  } finally {
    finishEditorActivity();
  }
}

function createMarkerRange(marker) {
  return new monaco.Range(
    marker.startLineNumber,
    marker.startColumn,
    marker.endLineNumber,
    marker.endColumn,
  );
}

function applySuggestionCase(word, suggestion, languageCode) {
  if (normalizeLanguageCode(languageCode) !== 'en') {
    return suggestion;
  }

  if (word.toUpperCase() === word) {
    return suggestion.toUpperCase();
  }

  if (
    word[0] &&
    word[0].toUpperCase() === word[0] &&
    word.slice(1).toLowerCase() === word.slice(1)
  ) {
    return suggestion[0].toUpperCase() + suggestion.slice(1);
  }

  return suggestion;
}

function normalizeSpellcheckSuggestions(suggestions) {
  if (!Array.isArray(suggestions)) {
    return [];
  }

  return suggestions.filter(
    (suggestion) => typeof suggestion === 'string' && suggestion,
  );
}

function formatSpellcheckSuggestionDisplayText(suggestion) {
  return String(suggestion || '')
    .replace(/\u200B/g, ' ')
    .replace(/\u200C/g, '[ZWNJ]')
    .replace(/\u200D/g, '[ZWJ]');
}

function formatSpellcheckSuggestionSpreadToken(character) {
  if (character === '\u200B') {
    return '[ZWSP]';
  }

  if (character === '\u200C') {
    return '[ZWNJ]';
  }

  if (character === '\u200D') {
    return '[ZWJ]';
  }

  return character;
}

function formatKhmerSpellcheckMarkerMessageWord(word) {
  const spreadTokens = Array.from(String(word || '')).map(
    formatSpellcheckSuggestionSpreadToken,
  );
  let wordSpreading = spreadTokens.join('​');
  if (wordSpreading.length > SPELLCHECK_KHMER_MARKER_MAX_SPREAD_LENGTH) {
    wordSpreading = `${wordSpreading.slice(
      0,
      SPELLCHECK_KHMER_MARKER_MAX_SPREAD_LENGTH,
    )}...`;
  }
  return spreadTokens.length ? `'${wordSpreading}'` : '""';
}

function formatSpellcheckMarkerMessageWord(word, languageCode = '') {
  if (isKhmerSpellcheckLanguageCode(languageCode)) {
    return formatKhmerSpellcheckMarkerMessageWord(word);
  }

  return `"${formatSpellcheckSuggestionDisplayText(word)}"`;
}

function formatKhmerSpellcheckSuggestionSpreadText(suggestion) {
  return Array.from(String(suggestion || ''))
    .map((character) => `${formatSpellcheckSuggestionSpreadToken(character)}`)
    .join('​');
}

function formatSpellcheckSuggestionLabel(suggestion, languageCode = '') {
  const displayText = formatSpellcheckSuggestionDisplayText(suggestion);

  if (!displayText || !isKhmerSpellcheckLanguageCode(languageCode)) {
    return displayText;
  }

  const spreadText = formatKhmerSpellcheckSuggestionSpreadText(suggestion);
  return spreadText ? `${displayText}: ${spreadText}` : displayText;
}

function formatAddToCustomDictionaryLabel(word) {
  const displayText = formatSpellcheckSuggestionDisplayText(word);

  return displayText
    ? `Add "${displayText}" to Custom Dictionary`
    : 'Add to Custom Dictionary';
}

async function loadProviderSuggestions(provider, word, languageCode) {
  if (!provider?.getSuggestions || !word) {
    return [];
  }

  try {
    return normalizeSpellcheckSuggestions(await provider.getSuggestions(word));
  } catch (error) {
    console.error(
      `Failed to load ${languageCode} spellcheck suggestions for "${word}".`,
      error,
    );
    return [];
  }
}

async function loadProviderPrefixSuggestions(
  provider,
  word,
  languageCode,
  limit,
) {
  if (!provider || !word) {
    return [];
  }

  if (typeof provider.getPrefixSuggestions === 'function') {
    try {
      return normalizeSpellcheckSuggestions(
        await provider.getPrefixSuggestions(word, limit),
      );
    } catch (error) {
      console.error(
        `Failed to load ${languageCode} spellcheck prefix suggestions for "${word}".`,
        error,
      );
      return [];
    }
  }

  return loadProviderSuggestions(provider, word, languageCode);
}

async function loadFallbackProviderSuggestions(languageCode, word, provider) {
  const specification = getSpellcheckSpecification(languageCode);
  if (!specification || !word) {
    return [];
  }

  if (typeof specification.providerFactory === 'function') {
    return [];
  }

  const fallbackProvider = createSpellcheckProvider(
    languageCode,
    specification,
  );
  if (!fallbackProvider || fallbackProvider === provider) {
    return [];
  }

  try {
    await fallbackProvider.initialize?.();

    if (!fallbackProvider.isReady?.()) {
      return [];
    }

    return normalizeSpellcheckSuggestions(
      await fallbackProvider.getSuggestions(word),
    );
  } catch (error) {
    console.error(
      `Failed to recover ${languageCode} spellcheck suggestions for "${word}".`,
      error,
    );
    return [];
  } finally {
    fallbackProvider.dispose?.();
  }
}

function getCodeActionLanguageCandidates(word) {
  const candidateLanguageCodes = [];
  const detectedLanguageCode = detectLanguageCode(word);

  if (detectedLanguageCode) {
    candidateLanguageCodes.push(detectedLanguageCode);
  }

  getEnabledSpellcheckLanguageCodes().forEach((languageCode) => {
    if (candidateLanguageCodes.includes(languageCode)) {
      return;
    }

    const provider = getSpellcheckProvider(languageCode);
    if (!provider?.shouldCheckWord?.(word)) {
      return;
    }

    candidateLanguageCodes.push(languageCode);
  });

  return Array.from(
    new Set(candidateLanguageCodes.map(normalizeLanguageCode).filter(Boolean)),
  );
}

function getQuickFixLanguageCandidates(word, preferredLanguageCode = '') {
  const normalizedPreferredLanguageCode = normalizeLanguageCode(
    preferredLanguageCode,
  );

  if (normalizedPreferredLanguageCode) {
    return supportsSpellcheckQuickFixLanguage(normalizedPreferredLanguageCode)
      ? [normalizedPreferredLanguageCode]
      : [];
  }

  return getCodeActionLanguageCandidates(word).filter(
    supportsSpellcheckQuickFixLanguage,
  );
}

async function resolveCodeActionSuggestions(word, candidateLanguageCodes) {
  const resolvedCandidateLanguageCodes = Array.isArray(candidateLanguageCodes)
    ? candidateLanguageCodes
    : getQuickFixLanguageCandidates(word);
  const shouldLogTiming = resolvedCandidateLanguageCodes.some(
    isKhmerSpellcheckLanguageCode,
  );
  const resolveStartTime = shouldLogTiming ? getSpellcheckTimingNow() : 0;
  let attemptCount = 0;
  let resolvedLanguageCode = '';
  let suggestionCount = 0;

  try {
    for (const languageCode of resolvedCandidateLanguageCodes) {
      const provider = getSpellcheckProvider(languageCode);
      if (!provider) {
        continue;
      }

      await ensureSpellcheckLanguageReady(languageCode);

      if (!provider.isReady()) {
        continue;
      }

      const candidateWords = [word];
      const normalizedCandidateWord = normalizeWord(word, languageCode);

      if (normalizedCandidateWord && normalizedCandidateWord !== word) {
        candidateWords.push(normalizedCandidateWord);
      }

      for (const candidateWord of candidateWords) {
        attemptCount += 1;

        let suggestions = await loadProviderSuggestions(
          provider,
          candidateWord,
          languageCode,
        );

        if (
          !suggestions.length &&
          normalizeLanguageCode(languageCode) !== 'en'
        ) {
          suggestions = await loadFallbackProviderSuggestions(
            languageCode,
            candidateWord,
            provider,
          );
        }

        if (suggestions.length) {
          resolvedLanguageCode =
            normalizeLanguageCode(languageCode) || languageCode;
          suggestionCount = suggestions.length;
          return {
            languageCode,
            suggestions,
          };
        }
      }
    }

    return null;
  } finally {
    if (shouldLogTiming) {
      logKhmerSpellcheckTiming(
        'quick fix resolve',
        resolveStartTime,
        `chars=${getSpellcheckWordCharacterCount(word)} candidates=${resolvedCandidateLanguageCodes.length} candidateCodes=${resolvedCandidateLanguageCodes.join(',') || 'none'} attempts=${attemptCount} language=${resolvedLanguageCode || 'none'} suggestions=${suggestionCount}`,
      );
    }
  }
}

async function createCodeActionsForMarker(model, marker, seenActions) {
  const markerRange = createMarkerRange(marker);
  const word = model.getValueInRange(markerRange);
  const candidateLanguageCodes = getQuickFixLanguageCandidates(
    word,
    marker?.origin,
  );
  const shouldLogTiming = isKhmerSpellcheckMarker(model, marker);
  const actionStartTime = shouldLogTiming ? getSpellcheckTimingNow() : 0;
  let actionCount = 0;
  let resolvedLanguageCode = '';

  if (!candidateLanguageCodes.length) {
    return [];
  }

  try {
    const resolvedSuggestions = await resolveCodeActionSuggestions(
      word,
      candidateLanguageCodes,
    );
    const actions = [];

    resolvedLanguageCode =
      normalizeLanguageCode(marker?.origin) ||
      normalizeLanguageCode(resolvedSuggestions?.languageCode) ||
      normalizeLanguageCode(candidateLanguageCodes[0]) ||
      '';

    if (
      resolvedLanguageCode &&
      !hasSpellcheckCustomDictionaryWord(resolvedLanguageCode, word)
    ) {
      const normalizedCustomDictionaryWord =
        normalizeSpellcheckCustomDictionaryWord(word, resolvedLanguageCode);
      const actionKey = normalizedCustomDictionaryWord
        ? `custom-dictionary:${resolvedLanguageCode}:${normalizedCustomDictionaryWord}`
        : '';

      if (actionKey && !seenActions.has(actionKey)) {
        const actionTitle = formatAddToCustomDictionaryLabel(word);

        seenActions.add(actionKey);
        actions.push({
          title: actionTitle,
          kind: QUICK_FIX_KIND,
          diagnostics: [marker],
          command: {
            id: ADD_TO_CUSTOM_DICTIONARY_COMMAND_ID,
            title: actionTitle,
            arguments: [
              {
                languageCode: resolvedLanguageCode,
                word,
              },
            ],
          },
          isPreferred: true,
        });
      }
    }

    if (resolvedSuggestions) {
      const { languageCode, suggestions } = resolvedSuggestions;

      resolvedLanguageCode =
        normalizeLanguageCode(languageCode) || languageCode;

      suggestions.forEach((suggestion, index) => {
        const replacement = applySuggestionCase(word, suggestion, languageCode);
        const actionKey = `${marker.startLineNumber}:${marker.startColumn}:${replacement}`;
        if (seenActions.has(actionKey)) {
          return;
        }

        seenActions.add(actionKey);
        actions.push({
          title: formatSpellcheckSuggestionLabel(
            replacement,
            resolvedLanguageCode || languageCode,
          ),
          kind: QUICK_FIX_KIND,
          diagnostics: [marker],
          edit: {
            edits: [
              {
                resource: model.uri,
                textEdit: {
                  range: markerRange,
                  text: replacement,
                },
              },
            ],
          },
          isPreferred: index === 0 && !actions.length,
        });
      });
    }

    actionCount = actions.length;
    return actions;
  } finally {
    if (shouldLogTiming) {
      logKhmerSpellcheckTiming(
        'quick fix marker actions',
        actionStartTime,
        `line=${marker.startLineNumber} chars=${getSpellcheckWordCharacterCount(word)} language=${resolvedLanguageCode || 'none'} actions=${actionCount}`,
      );
    }
  }
}

function getMarkerWord(model, marker) {
  if (!model || !marker) {
    return '';
  }

  return model.getValueInRange(createMarkerRange(marker));
}

function isKhmerSpellcheckMarker(model, marker) {
  if (String(marker?.code) !== SPELLCHECK_CODE) {
    return false;
  }

  const markerLanguageCode = normalizeLanguageCode(marker?.origin);
  if (markerLanguageCode === 'km') {
    return true;
  }

  const word = getMarkerWord(model, marker);
  const normalizedWord = normalizeWord(word, 'km');
  return Boolean(normalizedWord && hasKhmerBaseLetter(normalizedWord));
}

async function getKhmerSegmentationReplacement(model, marker) {
  const word = getMarkerWord(model, marker);
  const shouldLogTiming = Boolean(
    model && isKhmerSpellcheckMarker(model, marker),
  );
  const lookupStartTime = shouldLogTiming ? getSpellcheckTimingNow() : 0;
  let attemptedCandidateCount = 0;
  let candidateCount = 0;
  let foundReplacement = false;
  let ready = false;

  try {
    if (!model || !isKhmerSpellcheckMarker(model, marker)) {
      return '';
    }

    const provider = getSpellcheckProvider('km');
    if (!provider?.getSegmentationSuggestion) {
      return '';
    }

    await ensureSpellcheckLanguageReady('km');
    ready = provider.isReady();

    if (!ready) {
      return '';
    }

    const candidateWords = [word];
    const normalizedCandidateWord = normalizeWord(word, 'km');

    if (normalizedCandidateWord && normalizedCandidateWord !== word) {
      candidateWords.push(normalizedCandidateWord);
    }

    candidateCount = candidateWords.length;

    for (const candidateWord of candidateWords) {
      attemptedCandidateCount += 1;

      try {
        const replacement =
          await provider.getSegmentationSuggestion(candidateWord);
        if (
          typeof replacement === 'string' &&
          replacement &&
          replacement !== candidateWord
        ) {
          foundReplacement = true;
          return replacement;
        }
      } catch (error) {
        console.error(
          `Failed to load Khmer segmentation suggestion for "${candidateWord}".`,
          error,
        );
      }
    }

    return '';
  } finally {
    if (shouldLogTiming) {
      logKhmerSpellcheckTiming(
        'segmentation lookup',
        lookupStartTime,
        `chars=${getSpellcheckWordCharacterCount(word)} candidates=${candidateCount} attempts=${attemptedCandidateCount} found=${String(foundReplacement)} ready=${String(ready)}`,
      );
    }
  }
}

async function applyKhmerSegmentationMarkerEdit(editor, marker) {
  const model = editor?.getModel?.();
  if (!model) {
    return false;
  }

  const finishEditorActivity = startEditorActivity();
  const applyStartTime = getSpellcheckTimingNow();
  let paintWaitMs = 0;
  let replacementLookupMs = 0;
  let editMs = 0;
  let applied = false;

  try {
    const paintWaitStartTime = getSpellcheckTimingNow();

    await new Promise((resolve) => {
      if (typeof globalThis.requestAnimationFrame === 'function') {
        globalThis.requestAnimationFrame(() => resolve());
        return;
      }

      globalThis.setTimeout(resolve, 0);
    });

    paintWaitMs = getSpellcheckTimingNow() - paintWaitStartTime;

    const replacementLookupStartTime = getSpellcheckTimingNow();

    const replacement = await getKhmerSegmentationReplacement(model, marker);
    replacementLookupMs = getSpellcheckTimingNow() - replacementLookupStartTime;

    if (!replacement) {
      return false;
    }

    const editStartTime = getSpellcheckTimingNow();

    applied = editor.executeEdits('open-lyric-khmer-segmentation', [
      {
        range: createMarkerRange(marker),
        text: replacement,
      },
    ]);

    editMs = getSpellcheckTimingNow() - editStartTime;
    return applied;
  } finally {
    finishEditorActivity();

    logKhmerSpellcheckTiming(
      'segmentation apply',
      applyStartTime,
      `paintWait=${paintWaitMs.toFixed(1)}ms lookup=${replacementLookupMs.toFixed(1)}ms edit=${editMs.toFixed(1)}ms applied=${String(applied)}`,
    );
  }
}

function disposeSpellcheckCodeActions() {
  spellcheckRuntime.codeActionProviderDisposable?.dispose?.();
  spellcheckRuntime.codeActionProviderDisposable = null;
  spellcheckRuntime.codeActionProviderRegistered = false;
}

function registerSpellcheckCodeActions(languageCodes = []) {
  const hasQuickFixLanguage = Array.isArray(languageCodes)
    ? languageCodes.some(supportsSpellcheckQuickFixLanguage)
    : false;

  if (!hasQuickFixLanguage) {
    disposeSpellcheckCodeActions();
    return;
  }

  if (spellcheckRuntime.codeActionProviderRegistered) {
    return;
  }

  const provider = {
    async provideCodeActions(model, _range, context) {
      const spellcheckMarkers = context.markers.filter(
        (marker) => String(marker.code) === SPELLCHECK_CODE,
      );
      const shouldLogTiming = shouldLogKhmerSpellcheckMarkers(
        model,
        spellcheckMarkers,
      );
      const quickFixSearchStartTime = shouldLogTiming
        ? getSpellcheckTimingNow()
        : 0;
      let actionCount = 0;

      if (!spellcheckMarkers.length) {
        return {
          actions: [],
          dispose() {},
        };
      }

      if (!isInvokedSpellcheckCodeActionRequest(context)) {
        return {
          actions: [],
          dispose() {},
        };
      }

      const finishEditorActivity = startEditorActivity();

      try {
        const seenActions = new Set();
        const actionGroups = await Promise.all(
          spellcheckMarkers.map((marker) =>
            createCodeActionsForMarker(model, marker, seenActions),
          ),
        );
        const actions = actionGroups.flat();
        actionCount = actions.length;

        return {
          actions,
          dispose() {},
        };
      } finally {
        finishEditorActivity();

        if (shouldLogTiming) {
          logKhmerSpellcheckTiming(
            'quick fix search',
            quickFixSearchStartTime,
            `markers=${spellcheckMarkers.length} actions=${actionCount}`,
          );
        }
      }
    },
  };
  const disposables = SPELLCHECK_CODE_ACTION_LANGUAGE_IDS.map((languageId) =>
    monaco.languages.registerCodeActionProvider(languageId, provider),
  );

  spellcheckRuntime.codeActionProviderDisposable = {
    dispose() {
      disposables.forEach((disposable) => {
        disposable?.dispose?.();
      });
    },
  };

  spellcheckRuntime.codeActionProviderRegistered = true;
}

async function ensureSpellcheckReady(
  languageCodes = getEnabledSpellcheckLanguageCodes(),
) {
  const normalizedLanguages = Array.from(
    new Set(languageCodes.map(normalizeLanguageCode).filter(Boolean)),
  );
  registerSpellcheckCodeActions(normalizedLanguages);

  if (!normalizedLanguages.length) {
    return new Map();
  }

  const readyStates = await Promise.all(
    normalizedLanguages.map(async (languageCode) => [
      languageCode,
      await ensureSpellcheckLanguageReady(languageCode),
    ]),
  );

  return new Map(readyStates);
}

async function loadAutocompleteSpellcheckSuggestions(
  word,
  { languageCodes = getEnabledSpellcheckLanguageCodes(), limit = 8 } = {},
) {
  const normalizedWord = String(word || '');
  const maxSuggestions = Math.max(1, Number(limit) || 8);
  const resolvedLanguageCodes = Array.from(
    new Set(
      (Array.isArray(languageCodes) ? languageCodes : [languageCodes])
        .map(normalizeLanguageCode)
        .filter(Boolean),
    ),
  );
  const perLanguageLimit = Math.max(
    1,
    Math.ceil(maxSuggestions / Math.max(1, resolvedLanguageCodes.length)),
  );

  if (!normalizedWord || !resolvedLanguageCodes.length) {
    return [];
  }

  void ensureSpellcheckReady(resolvedLanguageCodes);

  const seenSuggestions = new Set();
  const resolvedSuggestions = [];

  const appendSuggestion = (languageCode, sourceLabel, suggestion) => {
    const replacement = applySuggestionCase(
      normalizedWord,
      suggestion,
      languageCode,
    );
    const suggestionKey = `${normalizeLanguageCode(languageCode) || languageCode}:${normalizeWord(replacement, languageCode) || replacement.toLocaleLowerCase()}`;

    if (seenSuggestions.has(suggestionKey)) {
      return false;
    }

    seenSuggestions.add(suggestionKey);
    resolvedSuggestions.push({
      languageCode,
      sourceLabel,
      suggestion: replacement,
    });
    return true;
  };

  for (const languageCode of resolvedLanguageCodes) {
    const provider = getSpellcheckProvider(languageCode);
    const specification = getSpellcheckSpecification(languageCode);
    const dictionarySourceLabel = specification?.displayName
      ? `${specification.displayName} dictionary`
      : `${String(languageCode || '').toUpperCase()} dictionary`;
    const customDictionarySourceLabel = specification?.displayName
      ? `${specification.displayName} custom dictionary`
      : `${String(languageCode || '').toUpperCase()} custom dictionary`;

    getSpellcheckCustomDictionaryPrefixSuggestions(
      languageCode,
      normalizedWord,
      perLanguageLimit,
    ).forEach((suggestion) => {
      appendSuggestion(languageCode, customDictionarySourceLabel, suggestion);
    });

    if (resolvedSuggestions.length >= maxSuggestions) {
      return resolvedSuggestions.slice(0, maxSuggestions);
    }

    if (!provider?.isReady?.()) {
      continue;
    }

    const candidateWords = [normalizedWord];
    const normalizedCandidateWord = normalizeWord(normalizedWord, languageCode);

    if (normalizedCandidateWord && normalizedCandidateWord !== normalizedWord) {
      candidateWords.push(normalizedCandidateWord);
    }

    for (const candidateWord of candidateWords) {
      const suggestions = await loadProviderPrefixSuggestions(
        provider,
        candidateWord,
        languageCode,
        perLanguageLimit,
      );

      if (!suggestions.length) {
        continue;
      }

      suggestions.forEach((suggestion) => {
        appendSuggestion(languageCode, dictionarySourceLabel, suggestion);
      });

      if (resolvedSuggestions.length >= maxSuggestions) {
        return resolvedSuggestions.slice(0, maxSuggestions);
      }
    }
  }

  return resolvedSuggestions.slice(0, maxSuggestions);
}

